//   { "errors": { "<field>": ["<message>"] } }
// This helper carries an HTTP status code alongside that body.
export class ApiError extends Error {
  status: number
  errors: Record<string, string[]>

  constructor(status: number, errors: Record<string, string[]>) {
    super('ApiError')
    this.status = status
    this.errors = errors
  }
}

// Convenience constructors for the error shapes exercised by the spec.
export const missingToken = () => new ApiError(401, { token: ['is missing'] })
export const invalidToken = () => new ApiError(401, { token: ['is invalid'] })
