import { scryptSync, randomBytes, timingSafeEqual } from 'node:crypto'
import jwt from 'jsonwebtoken'
import type { FastifyRequest } from 'fastify'
import { missingToken, invalidToken } from './errors.js'

const JWT_SECRET = process.env.JWT_SECRET || 'realworld-dev-secret'

// --- Password hashing (scrypt, no native dependency) ---

export function hashPassword(password: string): string {
  const salt = randomBytes(16)
  const derived = scryptSync(password, salt, 64)
  return `${salt.toString('hex')}:${derived.toString('hex')}`
}

export function verifyPassword(password: string, stored: string): boolean {
  const [saltHex, hashHex] = stored.split(':')
  if (!saltHex || !hashHex) return false
  const salt = Buffer.from(saltHex, 'hex')
  const expected = Buffer.from(hashHex, 'hex')
  const derived = scryptSync(password, salt, 64)
  return derived.length === expected.length && timingSafeEqual(derived, expected)
}

// --- JWT ---

export function signToken(userId: number): string {
  return jwt.sign({ id: userId }, JWT_SECRET, { expiresIn: '7d' })
}

// Extracts the bearer token from an `Authorization: Token <jwt>` header.
function extractToken(req: FastifyRequest): string | null {
  const header = req.headers.authorization
  if (!header) return null
  const [scheme, value] = header.split(' ')
  if (!value || (scheme !== 'Token' && scheme !== 'Bearer')) return null
  return value
}

// Required auth: throws 401 when no valid token is present.
export function requireUser(req: FastifyRequest): number {
  const token = extractToken(req)
  if (!token) throw missingToken()
  try {
    const payload = jwt.verify(token, JWT_SECRET) as { id: number }
    return payload.id
  } catch {
    throw invalidToken()
  }
}

// Optional auth: returns the user id when a valid token is present, else null.
export function optionalUser(req: FastifyRequest): number | null {
  const token = extractToken(req)
  if (!token) return null
  try {
    const payload = jwt.verify(token, JWT_SECRET) as { id: number }
    return payload.id
  } catch {
    return null
  }
}

