import { prisma } from './prisma.js'
import { signToken } from './auth.js'

// Prisma include used everywhere an article is serialized. `favorites` is
// filtered to the current user so we can cheaply tell whether they favorited it,
// while `_count` gives the total favorites count.
export function articleInclude(currentUserId: number | null) {
  return {
    author: true,
    tags: true,
    _count: { select: { favorites: true } },
    favorites: { where: { userId: currentUserId ?? 0 } },
  }
}

// Returns the set of user ids the current user follows (empty when anonymous).
async function followedIds(currentUserId: number | null): Promise<Set<number>> {
  if (!currentUserId) return new Set()
  const rows = await prisma.follow.findMany({
    where: { followerId: currentUserId },
    select: { followedId: true },
  })
  return new Set(rows.map((r) => r.followedId))
}

function iso(date: Date): string {
  return date.toISOString()
}

// Serializes a user record for /user and /users responses (includes a fresh token).
export function userJSON(user: any) {
  return {
    user: {
      email: user.email,
      username: user.username,
      bio: user.bio ?? null,
      image: user.image ?? null,
      token: signToken(user.id),
    },
  }
}

// Serializes an author into a RealWorld profile object.
function profileFrom(author: any, following: boolean) {
  return {
    username: author.username,
    bio: author.bio ?? null,
    image: author.image ?? null,
    following,
  }
}

export async function profileJSON(author: any, currentUserId: number | null) {
  const follows = await followedIds(currentUserId)
  return { profile: profileFrom(author, follows.has(author.id)) }
}

// Serializes a single article (with its `author` following flag resolved).
export async function articleJSON(
  article: any,
  currentUserId: number | null,
  opts: { includeBody?: boolean } = {},
) {
  const follows = await followedIds(currentUserId)
  return { article: articleView(article, follows, opts.includeBody ?? true) }
}

// Serializes a list of articles, batching the "following" lookup into one query.
export async function articlesJSON(
  articles: any[],
  count: number,
  currentUserId: number | null,
  opts: { includeBody?: boolean } = {},
) {
  const follows = await followedIds(currentUserId)
  return {
    articles: articles.map((a) => articleView(a, follows, opts.includeBody ?? false)),
    articlesCount: count,
  }
}

function articleView(article: any, follows: Set<number>, includeBody: boolean) {
  const view: Record<string, unknown> = {
    slug: article.slug,
    title: article.title,
    description: article.description,
    tagList: article.tags.map((t: any) => t.name).sort(),
    createdAt: iso(article.createdAt),
    updatedAt: iso(article.updatedAt),
