import type { FastifyInstance } from 'fastify'
import { prisma } from '../prisma.js'
import { hashPassword, verifyPassword, requireUser } from '../auth.js'
import { userJSON } from '../serialize.js'
import { blank, taken, invalidCredentials, notFound } from '../errors.js'

// Treats null / non-string / empty-after-trim as "blank".
function isBlank(value: unknown): boolean {
  return value == null || typeof value !== 'string' || value.trim() === ''
}

export async function userRoutes(app: FastifyInstance) {
  // Registration
  app.post('/api/users', async (req, reply) => {
    const { username, email, password } = (req.body as any)?.user ?? {}

    if (isBlank(username)) throw blank('username')
    if (isBlank(email)) throw blank('email')
    if (isBlank(password)) throw blank('password')

    if (await prisma.user.findUnique({ where: { username } })) throw taken('username')
    if (await prisma.user.findUnique({ where: { email } })) throw taken('email')

    const user = await prisma.user.create({
      data: { username, email, password: hashPassword(password) },
    })
    reply.code(201)
    return userJSON(user)
  })

  // Login
  app.post('/api/users/login', async (req) => {
    const { email, password } = (req.body as any)?.user ?? {}

    if (isBlank(email)) throw blank('email')
    if (isBlank(password)) throw blank('password')

    const user = await prisma.user.findUnique({ where: { email } })
    if (!user || !verifyPassword(password, user.password)) throw invalidCredentials()

    return userJSON(user)
  })

  // Get current user
  app.get('/api/user', async (req) => {
    const userId = requireUser(req)
    const user = await prisma.user.findUnique({ where: { id: userId } })
    if (!user) throw notFound('user')
    return userJSON(user)
  })

  // Update current user
  app.put('/api/user', async (req) => {
    const userId = requireUser(req)
    const patch = (req.body as any)?.user ?? {}
    const data: Record<string, unknown> = {}

    // username / email: required, non-nullable -> reject blank or null.
    for (const field of ['username', 'email'] as const) {
      if (field in patch) {
        if (isBlank(patch[field])) throw blank(field)
        data[field] = patch[field]
      }
    }

    // password: reject blank/null/short (< 8 chars), otherwise re-hash.
    if ('password' in patch) {
      const pw = patch.password
      if (isBlank(pw) || (pw as string).length < 8) throw blank('password')
      data.password = hashPassword(pw)
    }

    // bio / image: nullable; empty string normalizes to null.
    for (const field of ['bio', 'image'] as const) {
      if (field in patch) {
        const value = patch[field]
        data[field] = value === '' || value == null ? null : value
      }
    }

    // Enforce uniqueness when changing username/email to a value owned by another user.
    if (typeof data.username === 'string') {
      const existing = await prisma.user.findUnique({ where: { username: data.username } })
      if (existing && existing.id !== userId) throw taken('username')
    }
    if (typeof data.email === 'string') {
      const existing = await prisma.user.findUnique({ where: { email: data.email } })
      if (existing && existing.id !== userId) throw taken('email')
    }

    const user = await prisma.user.update({ where: { id: userId }, data })
    return userJSON(user)
  })
}

