import type { FastifyInstance } from 'fastify'
import { prisma } from '../prisma.js'
import { requireUser, optionalUser } from '../auth.js'
import { profileJSON } from '../serialize.js'
import { notFound } from '../errors.js'

export async function profileRoutes(app: FastifyInstance) {
  // Get a profile (optional auth to resolve `following`).
  app.get('/api/profiles/:username', async (req) => {
    const currentUserId = optionalUser(req)
    const { username } = req.params as { username: string }
    const user = await prisma.user.findUnique({ where: { username } })
    if (!user) throw notFound('profile')
    return profileJSON(user, currentUserId)
  })

  // Follow a profile.
  app.post('/api/profiles/:username/follow', async (req) => {
    const currentUserId = requireUser(req)
    const { username } = req.params as { username: string }
    const target = await prisma.user.findUnique({ where: { username } })
    if (!target) throw notFound('profile')

    await prisma.follow.upsert({
      where: { followerId_followedId: { followerId: currentUserId, followedId: target.id } },
      create: { followerId: currentUserId, followedId: target.id },
      update: {},
    })
    return profileJSON(target, currentUserId)
  })

  // Unfollow a profile.
  app.delete('/api/profiles/:username/follow', async (req) => {
    const currentUserId = requireUser(req)
    const { username } = req.params as { username: string }
    const target = await prisma.user.findUnique({ where: { username } })
    if (!target) throw notFound('profile')

    await prisma.follow.deleteMany({
      where: { followerId: currentUserId, followedId: target.id },
    })
    return profileJSON(target, currentUserId)
  })
}

