import type { FastifyInstance } from 'fastify'
import { randomBytes } from 'node:crypto'
import { prisma } from '../prisma.js'
import { requireUser, optionalUser } from '../auth.js'
import { articleInclude, articleJSON, articlesJSON } from '../serialize.js'
import { blank, notFound, forbidden, ApiError } from '../errors.js'

function isBlank(value: unknown): boolean {
  return value == null || typeof value !== 'string' || value.trim() === ''
}

function slugify(title: string): string {
  const base = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
  return `${base || 'article'}-${randomBytes(4).toString('hex')}`
}

function toInt(value: unknown, fallback: number): number {
  const n = parseInt(String(value ?? ''), 10)
  return Number.isFinite(n) && n >= 0 ? n : fallback
}

// Normalizes a tagList into a sorted, de-duplicated array of non-empty strings.
function normalizeTags(tagList: unknown): string[] {
  if (!Array.isArray(tagList)) return []
  const names = tagList.filter((t): t is string => typeof t === 'string' && t.trim() !== '')
  return [...new Set(names)]
}

async function connectTags(names: string[]) {
  return Promise.all(
    names.map((name) =>
      prisma.tag.upsert({ where: { name }, create: { name }, update: {} }),
    ),
  ).then((tags) => tags.map((t) => ({ id: t.id })))
}

export async function articleRoutes(app: FastifyInstance) {
  // Feed: articles authored by users the current user follows.
  // Registered before `/api/articles/:slug` so the static segment wins.
  app.get('/api/articles/feed', async (req) => {
    const currentUserId = requireUser(req)
    const { limit, offset } = req.query as Record<string, string>

    const follows = await prisma.follow.findMany({
      where: { followerId: currentUserId },
      select: { followedId: true },
    })
    const authorIds = follows.map((f) => f.followedId)
    const where = { authorId: { in: authorIds } }

    const [articles, count] = await Promise.all([
      prisma.article.findMany({
        where,
        include: articleInclude(currentUserId),
        orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
        take: toInt(limit, 20),
        skip: toInt(offset, 0),
      }),
      prisma.article.count({ where }),
    ])
    return articlesJSON(articles, count, currentUserId)
  })

  // List articles with optional filters.
  app.get('/api/articles', async (req) => {
    const currentUserId = optionalUser(req)
    const q = req.query as Record<string, string>

    const where: any = {}
    if (q.author) where.author = { username: q.author }
    if (q.tag) where.tags = { some: { name: q.tag } }
    if (q.favorited) where.favorites = { some: { user: { username: q.favorited } } }

    const [articles, count] = await Promise.all([
      prisma.article.findMany({
        where,
        include: articleInclude(currentUserId),
        orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
        take: toInt(q.limit, 20),
        skip: toInt(q.offset, 0),
      }),
      prisma.article.count({ where }),
    ])
    return articlesJSON(articles, count, currentUserId)
  })

  // Create an article.
  app.post('/api/articles', async (req, reply) => {
    const currentUserId = requireUser(req)
    const input = (req.body as any)?.article ?? {}

    if (isBlank(input.title)) throw blank('title')
    if (isBlank(input.description)) throw blank('description')
    if (isBlank(input.body)) throw blank('body')

    const tagIds = await connectTags(normalizeTags(input.tagList))
    const article = await prisma.article.create({
      data: {
        slug: slugify(input.title),
        title: input.title,
        description: input.description,
        body: input.body,
        authorId: currentUserId,
        tags: { connect: tagIds },
      },
      include: articleInclude(currentUserId),
    })
    reply.code(201)
    return articleJSON(article, currentUserId)
  })

  // Get a single article.
  app.get('/api/articles/:slug', async (req) => {
    const currentUserId = optionalUser(req)
    const { slug } = req.params as { slug: string }
    const article = await prisma.article.findUnique({
      where: { slug },
      include: articleInclude(currentUserId),
    })
    if (!article) throw notFound('article')
    return articleJSON(article, currentUserId)
  })

  // Update an article.
  app.put('/api/articles/:slug', async (req) => {
    const currentUserId = requireUser(req)
    const { slug } = req.params as { slug: string }
    const input = (req.body as any)?.article ?? {}

    const existing = await prisma.article.findUnique({ where: { slug } })
    if (!existing) throw notFound('article')
    if (existing.authorId !== currentUserId) throw forbidden('article')

    const data: any = { updatedAt: new Date() }
    for (const field of ['title', 'description', 'body'] as const) {
      if (field in input) {
        if (isBlank(input[field])) throw blank(field)
        data[field] = input[field]
      }
    }

    // tagList: absent -> keep; array -> replace; null (or other) -> reject.
    if ('tagList' in input) {
      if (!Array.isArray(input.tagList)) throw new ApiError(422, { tagList: ['is invalid'] })
      const tagIds = await connectTags(normalizeTags(input.tagList))
      data.tags = { set: tagIds }
    }

    const article = await prisma.article.update({
      where: { slug },
      data,
      include: articleInclude(currentUserId),
    })
    return articleJSON(article, currentUserId)
  })

  // Delete an article.
  app.delete('/api/articles/:slug', async (req, reply) => {
    const currentUserId = requireUser(req)
    const { slug } = req.params as { slug: string }

    const existing = await prisma.article.findUnique({ where: { slug } })
    if (!existing) throw notFound('article')
    if (existing.authorId !== currentUserId) throw forbidden('article')

    await prisma.article.delete({ where: { slug } })
    reply.code(204)
    return null
  })

  // Favorite an article.
  app.post('/api/articles/:slug/favorite', async (req) => {
    const currentUserId = requireUser(req)
    const { slug } = req.params as { slug: string }

    const existing = await prisma.article.findUnique({ where: { slug } })
    if (!existing) throw notFound('article')

    await prisma.favorite.upsert({
      where: { userId_articleId: { userId: currentUserId, articleId: existing.id } },
      create: { userId: currentUserId, articleId: existing.id },
      update: {},
    })
    const article = await prisma.article.findUnique({
      where: { slug },
      include: articleInclude(currentUserId),
    })
    return articleJSON(article, currentUserId)
  })

  // Unfavorite an article.
  app.delete('/api/articles/:slug/favorite', async (req) => {
    const currentUserId = requireUser(req)
    const { slug } = req.params as { slug: string }

    const existing = await prisma.article.findUnique({ where: { slug } })
    if (!existing) throw notFound('article')

    await prisma.favorite.deleteMany({
      where: { userId: currentUserId, articleId: existing.id },
    })
    const article = await prisma.article.findUnique({
      where: { slug },
      include: articleInclude(currentUserId),
    })
    return articleJSON(article, currentUserId)
  })
}

