    return articlesJSON(articles, count, currentUserId)
  })

  // Create an article.
  app.post('/api/articles', async (req, reply) => {
    const currentUserId = requireUser(req)
    const input = (req.body as any)?.article ?? {}

    if (isBlank(input.title)) throw blank('title')
    if (isBlank(input.description)) throw blank('description')
    if (isBlank(input.body)) throw blank('body')

    const tagIds = await connectTags(normalizeTags(input.tagList))
    const article = await prisma.article.create({
      data: {
        slug: slugify(input.title),
        title: input.title,
        description: input.description,
        body: input.body,
        authorId: currentUserId,
        tags: { connect: tagIds },
      },
      include: articleInclude(currentUserId),
    })
    reply.code(201)
    return articleJSON(article, currentUserId)
  })

  // Get a single article.
  app.get('/api/articles/:slug', async (req) => {
    const currentUserId = optionalUser(req)
    const { slug } = req.params as { slug: string }
    const article = await prisma.article.findUnique({
      where: { slug },
      include: articleInclude(currentUserId),
    })
    if (!article) throw notFound('article')
    return articleJSON(article, currentUserId)
  })

  // Update an article.
  app.put('/api/articles/:slug', async (req) => {
    const currentUserId = requireUser(req)
    const { slug } = req.params as { slug: string }
    const input = (req.body as any)?.article ?? {}

    const existing = await prisma.article.findUnique({ where: { slug } })
    if (!existing) throw notFound('article')
    if (existing.authorId !== currentUserId) throw forbidden('article')

    const data: any = { updatedAt: new Date() }
    for (const field of ['title', 'description', 'body'] as const) {
      if (field in input) {
        if (isBlank(input[field])) throw blank(field)
        data[field] = input[field]
      }
    }

    // tagList: absent -> keep; array -> replace; null (or other) -> reject.
    if ('tagList' in input) {
      if (!Array.isArray(input.tagList)) throw new ApiError(422, { tagList: ['is invalid'] })
      const tagIds = await connectTags(normalizeTags(input.tagList))
      data.tags = { set: tagIds }
    }

    const article = await prisma.article.update({
      where: { slug },
      data,
      include: articleInclude(currentUserId),
    })
    return articleJSON(article, currentUserId)
  })

  // Delete an article.
  app.delete('/api/articles/:slug', async (req, reply) => {
    const currentUserId = requireUser(req)
    const { slug } = req.params as { slug: string }

    const existing = await prisma.article.findUnique({ where: { slug } })
    if (!existing) throw notFound('article')
    if (existing.authorId !== currentUserId) throw forbidden('article')

    await prisma.article.delete({ where: { slug } })
    reply.code(204)
    return null
  })

  // Favorite an article.
  app.post('/api/articles/:slug/favorite', async (req) => {
    const currentUserId = requireUser(req)
    const { slug } = req.params as { slug: string }

    const existing = await prisma.article.findUnique({ where: { slug } })
    if (!existing) throw notFound('article')

    await prisma.favorite.upsert({
      where: { userId_articleId: { userId: currentUserId, articleId: existing.id } },
      create: { userId: currentUserId, articleId: existing.id },
      update: {},
    })
    const article = await prisma.article.findUnique({
      where: { slug },
      include: articleInclude(currentUserId),
    })
    return articleJSON(article, currentUserId)
  })

  // Unfavorite an article.
  app.delete('/api/articles/:slug/favorite', async (req) => {
    const currentUserId = requireUser(req)
    const { slug } = req.params as { slug: string }

    const existing = await prisma.article.findUnique({ where: { slug } })
    if (!existing) throw notFound('article')

    await prisma.favorite.deleteMany({
      where: { userId: currentUserId, articleId: existing.id },
    })
    const article = await prisma.article.findUnique({
      where: { slug },
      include: articleInclude(currentUserId),
    })
    return articleJSON(article, currentUserId)
  })
}

