import type { FastifyInstance } from 'fastify'
import { prisma } from '../prisma.js'
import { requireUser, optionalUser } from '../auth.js'
import { commentJSON, commentsJSON, followedIds } from '../serialize.js'
import { blank, notFound, forbidden } from '../errors.js'

export async function commentRoutes(app: FastifyInstance) {
  // Add a comment to an article.
  app.post('/api/articles/:slug/comments', async (req, reply) => {
    const currentUserId = requireUser(req)
    const { slug } = req.params as { slug: string }
    const body = (req.body as any)?.comment?.body

    const article = await prisma.article.findUnique({ where: { slug } })
    if (!article) throw notFound('article')
    if (body == null || typeof body !== 'string' || body.trim() === '') throw blank('body')

    const comment = await prisma.comment.create({
      data: { body, articleId: article.id, authorId: currentUserId },
      include: { author: true },
    })
    const follows = await followedIds(currentUserId)
    reply.code(201)
    return commentJSON(comment, follows.has(comment.authorId))
  })

  // List comments for an article.
  app.get('/api/articles/:slug/comments', async (req) => {
    const currentUserId = optionalUser(req)
    const { slug } = req.params as { slug: string }

    const article = await prisma.article.findUnique({ where: { slug } })
    if (!article) throw notFound('article')

    const comments = await prisma.comment.findMany({
      where: { articleId: article.id },
      include: { author: true },
      orderBy: { createdAt: 'asc' },
    })
    const follows = await followedIds(currentUserId)
    return commentsJSON(comments, follows)
  })

  // Delete a comment.
  app.delete('/api/articles/:slug/comments/:id', async (req, reply) => {
    const currentUserId = requireUser(req)
    const { slug, id } = req.params as { slug: string; id: string }

    const article = await prisma.article.findUnique({ where: { slug } })
    if (!article) throw notFound('article')

    const comment = await prisma.comment.findUnique({ where: { id: Number(id) } })
    if (!comment || comment.articleId !== article.id) throw notFound('comment')
    if (comment.authorId !== currentUserId) throw forbidden('comment')

    await prisma.comment.delete({ where: { id: comment.id } })
    reply.code(204)
    return null
  })
}

