import Fastify, { type FastifyInstance } from 'fastify'
import { ApiError } from './errors.js'
import { userRoutes } from './routes/users.js'
import { profileRoutes } from './routes/profiles.js'
import { articleRoutes } from './routes/articles.js'
import { commentRoutes } from './routes/comments.js'
import { tagRoutes } from './routes/tags.js'

export function buildApp(): FastifyInstance {
  const app = Fastify({ logger: false })

  // Accept an empty request body for POST/DELETE endpoints that carry no payload
  // (e.g. follow / favorite) even when a JSON content-type is set.
  app.addContentTypeParser(
    'application/json',
    { parseAs: 'string' },
    (_req, bodyString, done) => {
      if (bodyString === '' || bodyString == null) {
        done(null, undefined)
        return
      }
      try {
        done(null, JSON.parse(bodyString as string))
      } catch (err) {
        done(err as Error, undefined)
      }
    },
  )

  // Uniform RealWorld error responses.
  app.setErrorHandler((error, _req, reply) => {
    if (error instanceof ApiError) {
      reply.code(error.status).send({ errors: error.errors })
      return
    }
    // Malformed JSON body -> treat as a validation error rather than a 500.
    if ((error as any).statusCode === 400) {
      reply.code(422).send({ errors: { body: ['is invalid'] } })
      return
    }
    reply.code(500).send({ errors: { server: ['internal error'] } })
  })

  app.register(userRoutes)
  app.register(profileRoutes)
  app.register(articleRoutes)
  app.register(commentRoutes)
  app.register(tagRoutes)

  return app
}

